lessons,questions,models=[],[],[]
def tex(v):return s.latex(s.Rational(v.numerator,v.denominator) if isinstance(v,F) else s.sympify(v))
def math(v):return r'\('+tex(v)+r'\)'
def picture(name,alt):return '<p><img src="/assets/original/s1-counting/'+name+'.svg" alt="'+alt+'"></p>'
def ex(title,question,solution,key):return dict(title=title,question=question,solution=solution,verification=key)
def lesson(key,title,summary,ideas,mistakes,examples):
 lessons.append(dict(key=key,id='orig_9709_s1_count_'+key,title=title,summary=summary,objective=summary,before='<p>Work with exact integer counts and identify what makes two outcomes different. Probability applications also use the conditional sample space from the preceding chapter. All arrangements here are in a line or in labelled rows; circular arrangements are excluded.</p>',ideas=ideas,method='<ol><li>Decide whether order, object identity and group labels matter.</li><li>Choose a disjoint case split or a staged construction.</li><li>Count each allowed outcome once and restore internal orders if needed.</li><li>Check restrictions, impossible cases and any overcounting factor.</li><li>For a probability, use the same kind of equally likely outcome in numerator and denominator.</li></ol>',mistakes=mistakes,examples=examples))

lesson('distinct_arrangements','Distinct objects, factorials and position restrictions',
 'Choose an ordered sample space, then handle leading zeroes, blocks, distances and relative order without double-counting.',
 r'''<h3>The product rule counts a staged construction</h3><p>Multiply the number of choices at each stage when each permitted partial construction has the stated number of continuations. Add disjoint cases when that number depends on an earlier choice. Mutually exclusive cases are not multiplied together.</p>
 <h3>Factorials and ordered selections</h3><p>For non-negative integers, n! multiplies 1 through n, with 0!=1. For r distinct objects chosen and placed in order from n distinct objects,</p>\[{}^nP_r=\frac{n!}{(n-r)!},\qquad0\le r\le n.\]<p>Without repetition, the choices decrease after each position. If repetitions are allowed, the same count may remain available.</p>
 <h3>Leading zero and end conditions interact</h3><p>A number cannot start with zero. For an even number with distinct digits, split the last digit into zero and non-zero even cases: they leave different numbers of non-zero first choices.</p>
 <h3>Blocks, exact separation and relative order</h3><p>For two named objects together, treat them as one unit, arrange the units and restore their two internal orders. For exactly g objects between them, their positions differ by g+1. A relative order such as A before B is not an adjacency requirement.</p>'''+picture('block-orders','A pair of named objects forms one block with two possible internal orders'),
 ['Do not use combinations when the order matters.','Handle zero separately when forming numbers.','A block has internal orders only for distinguishable members.','Exactly g objects between two names differs from a minimum gap.'],[
 ex('A choice and an ordered programme differ',r'<p>Three of six different talks are selected. How many selections are possible, and how many ordered three-talk programmes?</p>',r'\[\begin{aligned}\text{selections}&=\binom63=20,\\\text{programmes}&=6\times5\times4=120.\end{aligned}\]<p>Each selection gives 3!=6 different programmes. Selecting a set does not assign its order.</p>','COUNT-ORDER'),
 ex('An even last digit changes the first choices',r'<p>Form a four-digit number from 0 to 5 without repeating a digit. Count all such numbers and the even ones.</p>',r'<p>There are five non-zero first choices, then five, four and three choices.</p>\[5\times5\times4\times3=300.\]<p>For even numbers split on the final digit.</p>\[\begin{aligned}\text{last }0&:5\times4\times3=60,\\\text{last }2\text{ or }4&:2\times4\times4\times3=96.\end{aligned}\]<p>The even count is 156. Using five first choices in the second case would reuse its non-zero final digit.</p>','COUNT-ZERO'),
 ex('A named pair is a block with two orders',r'<p>Six different people, including A and B, stand in a line. Find the counts with A and B adjacent and with them apart.</p>',r'\[\begin{aligned}\text{adjacent}&=2(5!)=240,\\\text{apart}&=6!-240=480.\end{aligned}\]<p>The five units are the pair-block and the four other people. The factor 2 restores AB and BA.</p>','COUNT-BLOCK'),
 ex('Relative order does not require consecutive places',r'<p>Six different objects include A, B and C. How many linear orders have A before B before C?</p>',r'<p>Every choice of their three positions has exactly one allowed order of A, B, C. Fill the other three positions freely.</p>\[\binom63\,3!=120.\]<p>Equivalently, one of the \(3!\) equally frequent relative orders is allowed, so the count is \(\frac{6!}{3!}\).</p>','COUNT-RELATIVE')])

lesson('repeated_objects','Repeated symbols, blocks and gap methods',
 'Count distinct visible patterns and use gaps to separate identical objects or enforce exactly one adjacent pair.',
 r'''<h3>Identical symbols do not acquire hidden labels</h3><p>If n symbols have repeated multiplicities a,b,…, the number of distinct full patterns is</p>\[\frac{n!}{a!b!\cdots}.\]<p>Swapping two identical A tiles does not create a new pattern. Physical tile selections may require a different model; the final lesson makes that distinction explicit.</p>
 <h3>Apply restrictions after deciding what is identical</h3><p>If an A must be first, remove one A and recount the remaining multiplicities. A block AA has only one internal pattern; a block AB of distinct symbols has two if either order is allowed.</p>
 <h3>Arrange the ordinary objects, then choose gaps</h3><p>n distinct ordinary objects leave n+1 gaps, including both ends. Place at most one identical special object in each chosen gap to prevent adjacency. If the ends must be ordinary, use only the n−1 internal gaps.</p>'''+picture('available-gaps','Four ordinary objects create five gaps including both ends')+r'''
 <h3>Exactly one adjacent pair is a separate event</h3><p>With three identical red counters, a pair and a single red must occupy distinct gaps of the ordinary objects. Their gap roles differ, even though the red counters do not. Do not include a triple or count the same pair twice. If two pair-events overlap, remove their common arrangements with the correct multiplicity.</p>''',
 ['Do not label identical tiles and then forget to remove overcounting.','Remove a fixed symbol before applying the repeated-factor denominator.','The end gaps count unless the ends are restricted.','Exactly one adjacent pair excludes both no pair and a triple.'],[
 ex('Fix a repeated symbol, then recount',r'<p>Arrange A,A,A,B,B,C in a line. Count all distinct patterns and those beginning with A.</p>',r'\[\begin{aligned}\text{all}&=\frac{6!}{3!2!}=60,\\\text{first A}&=\frac{5!}{2!2!}=30.\end{aligned}\]<p>After fixing the first A, two As remain. Dividing the remaining patterns by 3! would remove too many orders.</p>','COUNT-REPEATED'),
 ex('Two pair-events overlap',r'<p>Arrange A,A,B,B,C,D. Find the counts with both AA and BB together, with exactly one pair together, and the latter probability given at least one pair is together in a uniform random pattern.</p>',r'<p>AA together gives \(\frac{5!}{2!}=60\); BB together also gives 60. Both together gives \(4!=24\). Let E mean exactly one pair together and H mean at least one pair together.</p>\[\begin{aligned}N(E)&=60+60-2(24)\\&=72,\\N(H)&=60+60-24=96,\\\mathrm P(E\mid H)&=72/96=3/4.\end{aligned}\]','COUNT-OVERLAP'),
 ex('Separate two identical counters with ordinary objects',r'<p>Arrange four different numbered counters and two identical red counters. Count arrangements with the reds separated and with the reds adjacent.</p>',r'<p>Arrange the numbered counters in \(4!\) ways. There are five gaps for two separated reds.</p>\[\begin{aligned}\text{separated}&=4!\binom52=240,\\\text{adjacent}&=5!=120.\end{aligned}\]<p>The counts sum to \(360=\frac{6!}{2!}\), the total number of patterns.</p>','COUNT-GAPS'),
 ex('A pair and a single need different gaps',r'<p>Arrange three different ordinary counters and three identical red counters. Count no adjacent reds, exactly one red pair with the third red separate, and all three reds together.</p>',r'\[\begin{aligned}\text{no pair}&=3!\binom43=24,\\\text{one pair}&=3!\times4\times3=72,\\\text{triple}&=4!=24.\end{aligned}\]<p>In the middle case choose the pair-gap, then a different single-gap. The three cases total \(120=\frac{6!}{3!}\).</p>','COUNT-PAIR-SINGLE')])

lesson('selections','Combinations, composition and named-member restrictions',
 'Build unordered selections once, using disjoint compositions, complements and explicit membership conditions.',
 r'''<h3>An unordered selection has no internal order</h3>\[{}^nC_r=\binom nr=\frac{n!}{r!(n-r)!}.\]<p>Each r-subset of distinct objects has r! orders, which explains the division. Choosing people for different named offices is an ordered assignment, not just a subset.</p>
 <h3>Compose a group from disjoint categories</h3><p>Multiply category choices for one fixed composition. For at least or at most conditions, sum over all allowed integer compositions or subtract a disjoint complement. Every case must use the required total group size.</p>
 <h3>Exactly one, not both, and both-or-neither differ</h3><p>For two named members, split selections into neither, exactly one and both. A rule that they cannot both serve still allows exactly one; an all-or-none rule does not. Named-member conditions should be applied before filling the remaining places.</p>
 <h3>A construction must have a constant overcount to divide it away</h3><p>Choosing one person of each category first and then extra people may count a final group a different number of times depending on its composition. Division by one guessed factor cannot repair a variable overcount. Use final compositions instead.</p>''',
 ['Do not multiply an unordered group count by its internal orders.','Include every feasible composition exactly once.','Cannot both serve does not mean both are absent.','A variable overcount cannot be corrected by one constant divisor.'],[
 ex('A prescribed composition uses a product',r'<p>Choose two engineers from five and three designers from six. Everyone is different and no offices are assigned. How many teams are possible?</p>',r'\[\binom52\binom63=10\times20=200.\]<p>Within-team order is irrelevant. No further factor of 5! is needed.</p>','COUNT-COMPOSITION'),
 ex('Partition by the number of named members',r'<p>Select three of seven different people including A and B. Count selections containing exactly one of them, both, and neither.</p>',r'\[\begin{aligned}\text{exactly one}&=2\binom52=20,\\\text{both}&=\binom51=5,\\\text{neither}&=\binom53=10.\end{aligned}\]<p>The three disjoint counts sum to 35=\(\binom73\).</p>','COUNT-NAMED'),
 ex('At least two specialists has three compositions',r'<p>Choose four people from six specialists and four trainees, with at least two specialists. Count the allowed teams.</p>',r'\[\begin{aligned}N&=\binom62\binom42+\binom63\binom41\\&\quad+\binom64\binom40\\&=90+80+15=185.\end{aligned}\]<p>The complement gives the same result: 210−1−24=185. Zero and exactly one specialist are the forbidden compositions.</p>','COUNT-AT-LEAST'),
 ex('Two similar-sounding restrictions allow different teams',r'<p>Choose four of ten different people including A and B. Count teams if they cannot both serve. Separately count teams if either both serve or neither serves.</p>',r'\[\begin{aligned}\text{cannot both}&=\binom{10}{4}-\binom82\\&=182,\\\text{both or neither}&=\binom82+\binom84\\&=98.\end{aligned}\]<p>The first condition allows teams containing exactly one of the two names; the second excludes those teams.</p>','COUNT-RESTRICTIONS')])

lesson('allocations','Labelled groups, unnamed divisions and rows of seats',
 'Identify which group swaps create a new allocation, and distinguish numbered positions from group membership.',
 r'''<h3>Named groups are distinct destinations</h3><p>For labelled groups of prescribed sizes a,b,…, with no internal order, choose members successively or use \(\frac{n!}{a!b!\cdots}\). Do not divide for swapping destinations that are actually named.</p>
 <h3>Only equivalent unnamed groups can be exchanged</h3><p>For non-empty unnamed groups of equal size, remove the permutations of those group labels. With different prescribed sizes, groups are already distinguished by size. Divide only for equal-size groups, not automatically by the factorial of the total number of groups.</p>'''+picture('group-swap','Exchanging two unnamed triples does not create a different division')+r'''
 <h3>Fixing one person can avoid a symmetry correction</h3><p>For two unnamed equal-sized teams, identify one team as the team containing a particular person. Choose that person’s teammates and let the rest form the other team. This counts every division exactly once.</p>
 <h3>Rows and empty seats need their actual labels</h3><p>In labelled rows of numbered seats, every position is different. After choosing a group for one row, restore the orders within the rows. Empty positions have no personal identities: do not multiply by a factorial of identical empty slots. Adjacency within a row does not cross to the next row.</p>''',
 ['Named destinations must not be swapped away.','Only equal-size unnamed groups share the same label symmetry.','Membership alone does not assign numbered seats.','Identical empty slots are not different passengers.'],[
 ex('Two unnamed triples have a twofold label symmetry',r'<p>Divide six different people into two teams of three. Count allocations to named teams East and West, then divisions with no team names.</p>',r'\[\begin{aligned}\text{named}&=\binom63=20,\\\text{unnamed}&=\frac{20}{2!}=10.\end{aligned}\]<p>Alternatively, choose two partners for A: \(\binom52=10\). The other three people form the other team.</p>','COUNT-TEAMS'),
 ex('An unequal third group does not supply another symmetry',r'<p>Nine different people form groups of sizes 4,4,1. Count allocations to named groups of those sizes and divisions without group names.</p>',r'\[\begin{aligned}\text{named}&=\binom94\binom54=630,\\\text{unnamed}&=\frac{630}{2!}=315.\end{aligned}\]<p>Only the two four-person groups can be exchanged. The singleton is distinguished by its size, so division by \(3!\) would be incorrect.</p>','COUNT-UNEQUAL-GROUPS'),
 ex('Sharing a row is weaker than adjacency',r'<p>Six different people fill two labelled rows of three numbered seats. Count arrangements with A and B in the same row, with them adjacent, and find the adjacent probability conditional on sharing a row.</p>',r'<p>Let S mean same row and J mean adjacent. For S choose the row, place A and B in two distinct seats, then seat the other four people.</p>\[\begin{aligned}N(S)&=2({}^3P_2)4!=288,\\N(J)&=2\times2\times2\times4!=192,\\\mathrm P(J\mid S)&=192/288=2/3.\end{aligned}\]<p>For J choose the row, the left or right adjacent pair, the order AB or BA, then arrange the others. The two edge positions in a row are not adjacent to each other.</p>','COUNT-ROWS'),
 ex('Empty positions are indistinguishable gaps',r'<p>A rack has seven positions in a line. Place four different cases, leaving three empty positions. Count all arrangements, those with all empties consecutive, and those with no adjacent empty positions.</p>',r'\[\begin{aligned}\text{all}&={}^7P_4=840,\\\text{empty block}&=5!=120,\\\text{no adjacency}&=4!\binom53=240.\end{aligned}\]<p>The final two events are not complements when there are three empty positions; a run of two empties is a further possibility.</p>','COUNT-EMPTY')])

lesson('mixed_counting','Mixed constructions and conditional counting probabilities',
 'Combine choosing and ordering, match physical sample spaces, and handle overlapping restrictions before conditioning.',
 r'''<h3>Choose and then arrange only when both stages matter</h3><p>If a condition depends on whether a named object was selected, split on that membership first. A single multiplication works only if every permitted selection has the same number of allowed orders.</p>
 <h3>Visible patterns need not be equally likely</h3><p>Different physical tiles carrying the same letter can produce the same visible selection. A uniform random physical subset weights each pattern by how many physical subsets realise it. Do not divide by the number of visible patterns unless uniformity over those patterns is stated.</p>
 <h3>Overlapping adjacency events share arrangements</h3><p>If E means AB adjacent and F means BC adjacent, their intersection requires B between A and C in a three-person block. It is not two independent pair-blocks. Exactly one needs the intersection removed twice; a union removes it once.</p>
 <h3>A conditional count has a restricted denominator</h3>\[\mathrm P(E\mid H)=\frac{N(E\cap H)}{N(H)}.\]<p>This count ratio is valid when the original elementary outcomes are equally likely and N(H)&gt;0. Use physical subsets on both sides, or arrangements on both sides. In paired-member selections, count complete pairs and single representatives from other pairs without accidentally completing another pair.</p>''',
 ['Some selections have different numbers of allowed orders.','A uniform physical subset does not make all visible patterns equiprobable.','Overlapping blocks cannot be counted as disjoint blocks.','A conditional denominator counts the condition, not the whole original space.'],[
 ex('A selected name changes the available positions',r'<p>Choose four of seven different objects and arrange them in a line. If A is chosen, A must be first. How many arrangements are possible?</p>',r'\[\begin{aligned}\text{A included}&=\binom63\,3!=120,\\\text{A absent}&={}^6P_4=360,\\\text{total}&=480.\end{aligned}\]<p>The two cases are disjoint. They do not have the same number of arrangements per chosen subset.</p>','COUNT-CHOOSE-ORDER'),
 ex('Four patterns arise from six physical subsets',r'<p>There are physical tiles A1,A2,B,C, where A1 and A2 both display A. Two tiles are chosen uniformly. List the visible patterns and find the probabilities of at least one A and exactly one A.</p>',r'<p>The patterns are AA, AB, AC, BC. Their physical multiplicities are 1,2,2,1, totalling six equally likely subsets.</p>\[\begin{aligned}\mathrm P(\text{at least one A})&=5/6,\\\mathrm P(\text{exactly one A})&=4/6=2/3.\end{aligned}\]<p>The four visible patterns are not equally likely.</p>','COUNT-PHYSICAL'),
 ex('One person belongs to both adjacency events',r'<p>Six different people include A,B,C. In a uniform random line, E means AB adjacent and F means BC adjacent. Count their intersection and exactly-one event, then find P(E given at least one of E,F).</p>',r'<p>Each single event has \(2(5!)=240\) arrangements. Both require ABC or CBA as one block, giving \(2(4!)=48\). Let X mean exactly one of E and F occurs, and let \(H=E\cup F\).</p>\[\begin{aligned}N(X)&=240+240-2(48)\\&=384,\\N(H)&=240+240-48\\&=432,\\\mathrm P(E\mid H)&=240/432=5/9.\end{aligned}\]','COUNT-SHARED-BLOCKS'),
 ex('A complete pair leaves singles from different pairs',r'<p>Four pairs of distinct people form a pool of eight. Choose a four-person team. Count teams with exactly one complete pair and with two complete pairs; find the probability of exactly one given at least one complete pair.</p>',r'<p>Let E mean exactly one complete pair and H mean at least one complete pair.</p>\[\begin{aligned}N(E)&=4\binom32\,2^2=48,\\N(\text{two pairs})&=\binom42=6,\\\mathrm P(E\mid H)&=48/54=8/9.\end{aligned}\]<p>The remaining two members in the first case come from different remaining pairs. The 16 teams with no complete pair complete the total 70=\(\binom84\).</p>','COUNT-PAIRS')])

def field(key,label,value):return dict(key=key,label=label,type='number',expected=str(value))
def choice(key,label,value,options):return dict(key=key,label=label,type='choice',expected=value,options=options)
def quick(topic,family,v,title,prompt,fields,explanation,model):
 uid=f'M4U-9709-S1-COUNT-CHECK-{topic.upper()}-{family}-{v}'
 answer=''.join('<p>'+f['label']+': '+(f['options'][f['expected']] if f['type']=='choice' else math(f['expected']))+'</p>' for f in fields)
 questions.append(dict(id=uid,family_uid=f'M4U-9709-S1-COUNT-CHECK-{topic.upper()}-{family}',lesson=topic,title=title,collection='short' if v==0 else 'variant',prompt_html=prompt,answer_html=answer,solution_html='<p>'+explanation+'</p><h4>Complete answers</h4>'+answer,hint_html='<p>Identify what is distinct and whether order or group labels matter. Split disjoint cases, count each final outcome once, and use the stated conditional sample space.</p>',marks=len(fields),difficulty=2,fields=fields,parts=[dict(label='',marking_criteria=[dict(code='B1',marks=1,description_html='Complete correct answer for '+f['label']+'.') for f in fields])],verification=uid))
 models.append(dict(uid=uid,**model))

for v in range(2):
 n,r=(6,3) if v==0 else (7,2)
 quick('distinct_arrangements',1,v,'An ordered programme and a selected set',f'<p>Choose {r} of {n} different items. Find the number of ordered programmes, the number of unordered selections, and the number of programmes per selection.</p>',[field('ordered','Ordered programmes',perm(n,r)),field('selected','Unordered selections',comb(n,r)),field('factor','Orders per selection',fact(r))],'Each chosen set has r! orders. Reversing a programme generally creates a different outcome; reordering a set does not.',dict(kind='choose_order',n=n,r=r))
 m,r=(5,4) if v==0 else (4,3);allcount=m*perm(m,r-1);zero=perm(m,r-1);nonzero=(m//2)*(m-1)*perm(m-1,r-2)
 quick('distinct_arrangements',2,v,'The final zero changes the leading choices',f'<p>Form a {r}-digit number from 0 to {m} without repetition, with non-zero first digit. Count all numbers, even numbers ending in zero, even numbers ending in a non-zero digit, and all even numbers.</p>',[field('all','All valid numbers',allcount),field('zero','Even numbers ending in zero',zero),field('nonzero','Even numbers ending non-zero',nonzero),field('even','All even numbers',zero+nonzero)],'Choose the last digit first in the even cases. A non-zero even last digit removes one possible non-zero first choice.',dict(kind='digits',m=m,r=r))
 n=6 if v==0 else 5;together=2*fact(n-1)
 quick('distinct_arrangements',3,v,'A pair-block and a relative order',f'<p>{n} different people, including A and B, stand in a line. Count arrangements with A,B together, with them apart, and with A somewhere before B.</p>',[field('together','A and B together',together),field('apart','A and B apart',fact(n)-together),field('before','A before B',fact(n)//2)],'The block has AB and BA orders. A-before-B fixes only their relative order, not their distance.',dict(kind='block_relative',n=n))
 n,g=(6,2) if v==0 else (7,1);positions=2*(n-g-1);count=positions*fact(n-2)
 quick('distinct_arrangements',4,v,'Exact separation fixes a position difference',f'<p>{n} different people, including A and B, stand in a line. Exactly {g} people must stand between A and B. Find the ordered position choices for A,B, the total arrangements and the probability of the condition in a uniform random line.</p>',[field('positions','Ordered A,B position choices',positions),field('arrangements','Valid arrangements',count),field('probability','Probability of the exact separation',F(count,fact(n)))],'Their positions differ by g+1. Count the two orientations and arrange all other names in the remaining places.',dict(kind='separation',n=n,g=g))

 counts=[3,2,1] if v==0 else [2,2,2];n=sum(counts);total=fact(n)
 for multiplicity in counts:total//=fact(multiplicity)
 first=F(total*counts[0],n)
 quick('repeated_objects',1,v,'A fixed repeated symbol changes the remaining multiplicities','<p>Arrange '+', '.join(str(c)+' copies of '+a for c,a in zip(counts,'ABC'))+'. Equal letters are indistinguishable. Count all patterns, patterns beginning with A, and patterns whose last letter is not A.</p>',[field('total','All patterns',total),field('first','Patterns beginning with A',first),field('last_not','Patterns not ending in A',total-first)],'After fixing one A, reduce its multiplicity by one. The other remaining multiplicities are unchanged.',dict(kind='multiset',counts=counts))
 k=2 if v==0 else 1;both=fact(k+2);single=fact(k+3)//2;xor=2*single-2*both;union=2*single-both
 quick('repeated_objects',2,v,'Exactly one pair excludes their intersection',f'<p>Arrange A,A,B,B and {k} other tiles with different letters. Equal letters are indistinguishable. Count patterns with both AA and BB together, patterns with exactly one pair together, and the latter probability given at least one pair together in a uniform random pattern.</p>',[field('both','Both pairs together',both),field('xor','Exactly one pair together',xor),field('conditional','Exactly one given at least one',F(xor,union))],'Count each pair-event and their intersection. Exactly one removes the intersection twice; the conditional denominator removes it once.',dict(kind='two_pairs',k=k))
 n=4 if v==0 else 3;separated=fact(n)*comb(n+1,2);adj=fact(n+1);total=fact(n+2)//2
 quick('repeated_objects',3,v,'Choose gaps for two identical counters',f'<p>Arrange {n} different ordinary counters and two identical red counters in a line. Count patterns with no adjacent reds, with the reds together, and all patterns.</p>',[field('separated','No adjacent reds',separated),field('adjacent','Reds together',adj),field('total','All patterns',total)],'The ordinary order has n+1 gaps including both ends. Choose two distinct gaps for separated identical reds; do not multiply by 2!.',dict(kind='two_reds',n=n))
 n=3 if v==0 else 4
 quick('repeated_objects',4,v,'A separate single red must use another gap',f'<p>Arrange {n} different ordinary counters and three identical red counters. Count no adjacent reds, exactly one red pair with the third red separate, and all three reds together.</p>',[field('none','No adjacent reds',fact(n)*comb(n+1,3)),field('pair','One pair with the third separate',fact(n)*(n+1)*n),field('triple','All three together',fact(n+1))],'Choose three single gaps for no adjacency. For pair-plus-single the two gap roles differ, and the gaps must be distinct.',dict(kind='three_reds',n=n))

 a,b,r,t=(5,6,2,3) if v==0 else (4,5,2,2);favourable=comb(a,r)*comb(b,t);total=comb(a+b,r+t)
 quick('selections',1,v,'A composition fixes independent category choices',f'<p>Select a team of {r+t} from {a} distinct specialists and {b} distinct trainees. Count teams with exactly {r} specialists and {t} trainees, all teams, and the event probability under a uniform selection.</p>',[field('favourable','Teams of the stated composition',favourable),field('total','All teams',total),field('probability','Probability of the composition',F(favourable,total))],'Choose each category without order, multiply for this composition, and use the full subset count as denominator.',dict(kind='composition',a=a,b=b,r=r,t=t))
 n,r=(7,3) if v==0 else (8,4)
 quick('selections',2,v,'Exactly one, both and neither are disjoint',f'<p>Select {r} of {n} different people, including A and B. Count teams containing exactly one of A,B, both, and neither.</p>',[field('one','Exactly one named member',2*comb(n-2,r-1)),field('both','Both named members',comb(n-2,r-2)),field('neither','Neither named member',comb(n-2,r))],'First decide which named members are included, then fill the remaining places from the other n−2 people.',dict(kind='named',n=n,r=r))
 a,b,r,minimum=(6,4,4,2) if v==0 else (5,3,4,3);favourable=sum(comb(a,k)*comb(b,r-k) for k in range(minimum,min(a,r)+1) if 0<=r-k<=b);total=comb(a+b,r)
 quick('selections',3,v,'At least includes every feasible composition',f'<p>Select {r} people from {a} distinct specialists and {b} distinct trainees, with at least {minimum} specialists. Find the permitted team count, all team count and event probability for a uniform selection.</p>',[field('favourable','Permitted teams',favourable),field('total','All teams',total),field('probability','Probability of the restriction',F(favourable,total))],'Add disjoint feasible specialist counts. Do not force an initial named subset that can be chosen several ways inside the same final team.',dict(kind='threshold',a=a,b=b,r=r,minimum=minimum))
 n,r=(10,4) if v==0 else (8,3);both=comb(n-2,r-2);neither=comb(n-2,r);opts={'A':'The two restrictions allow the same teams','B':'Both-or-neither excludes teams containing exactly one','C':'Cannot both means neither is allowed'} if v==0 else {'A':'Cannot both requires both people to be absent','B':'The rules are equivalent after swapping the names','C':'Both-or-neither excludes teams containing exactly one'}
