 sizes=[4,4,1] if v==0 else [3,3,2];n=sum(sizes);total=comb(n,sizes[0])*comb(n-sizes[0],sizes[1]);opts={'A':'Divide by 3! because there are three groups','B':'Divide by 2! for the two equal-size unnamed groups','C':'Never divide when groups are unnamed'} if v==0 else {'A':'Divide by 3! for every three-group division','B':'Divide by the factorial of the smallest group size','C':'Divide by 2! for the two equal-size unnamed groups'}
