 r=3 if v==0 else 4;n=2*r;same_row=2*perm(r,2)*fact(n-2);adj=2*(r-1)*2*fact(n-2)
 quick('allocations',3,v,'The row and the seats are labelled',f'<p>{n} different people fill two labelled rows of {r} numbered seats. A,B must share a row. Count those arrangements, count arrangements with A,B adjacent within their row, and find the adjacent probability given they share a row.</p>',[field('same','A,B in the same row',same_row),field('adjacent','A,B adjacent within a row',adj),field('conditional','Adjacent given same row',F(adj,same_row))],'Choose their row and positions before filling the remaining numbered seats. Adjacency does not cross a row boundary.',dict(kind='rows',r=r))
